import sys
from collections import deque

def main():
    sys.setrecursionlimit(1 << 25)
    n = int(sys.stdin.readline())
    p = [0] * (n + 1)
    c = [0] * (n + 1)
    children = [[] for _ in range(n + 1)]
    root = -1
    for i in range(1, n + 1):
        pi, ci = map(int, sys.stdin.readline().split())
        p[i] = pi
        c[i] = ci
        if pi == 0:
            root = i
        else:
            children[pi].append(i)

    a = [0] * (n + 1)
    possible = True

    def dfs(u):
        nonlocal possible
        if not possible:
            return
        subtree_size = 1
        subtree_c = c[u]
        for v in children[u]:
            dfs(v)
            subtree_size += 1
            subtree_c -= c[v]

        if subtree_c < 0 or subtree_c >= subtree_size:
            possible = False
            return

        a[u] = subtree_size - subtree_c
        for v in children[u]:
            if a[v] > a[u]:
                subtree_c -= 1
            if subtree_c < 0:
                possible = False
                return

    dfs(root)

    if not possible:
        print("NO")
        return

    def assign_values(u, parent_val):
        nonlocal possible
        if not possible:
            return
        current_val = a[u]
        if parent_val is not None and current_val <= parent_val:
            possible = False
            return
        for v in children[u]:
            assign_values(v, current_val)

    assign_values(root, None)

    if not possible:
        print("NO")
        return

    print("YES")
    for i in range(1, n + 1):
        print(a[i], end=' ')
    print()

if __name__ == "__main__":
    main()
